    "rel": "奇幻类/红楼梦/丧葬礼仪/C13-01-心愿未了.md",
    "face": "半夜，灯还亮着。甲半睡半醒，看见一个人走进来——就是前些日子还见过的那个人，神色和平常一样。\n\n来的人在甲旁边站住，笑着说：我今天要走了，你也不送我。咱们平日交好，我舍不得你，来跟你道别。我还有一件心愿没了，非得告诉你不可，别人未必顶用。\n\n甲问是什么心愿。\n\n这人说：这个家如今热闹，已经快一百年了。可是什么样的热闹都长不了。趁现在还在盛时，置一份产业、立一条规矩——往后祭祖、族里子弟读书的花费都从这里出，全族定下规矩，按房轮着管。这样就算往后败了，子孙回家读书种地，也有个退路。\n\n又说：往后还有两件要紧的。一件是不久还有一桩喜事。一件是，这席，总有散的那天。\n\n临走留下两句话，叫甲记着。\n\n甲还想再问，外面传来了报丧的响声。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理，也要确认这是玩家这个世界里“死者能与活人说话”的那套机制（梦、显形、附身、临终的最后一封信、留在机器里的一段话都可以）。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是玩家，也可以是当家的人、管家里钱粮的人、新寡、掌着账本的那一个。来的人在甲心里必须有分量——甲要是根本不理会，这张卡就失效。\n\n**玩家在哪**：玩家可以就是甲，当场听见这些话，信、不信、记不记得住都在他；可以是那位已经不在的人，由玩家来决定到底说不说、说多少；可以不在场，日后只从别人嘴里听到“她临走还惦记着家里的事”。如果玩家就是那位亡人，卡的重点变成“你醒着的时候没能说完的话，现在要不要说完”。\n\n**来的人是什么状态**：正史里她这时已经不在人世了。她可以是借着梦来的、显个影来的、借别人的口来说的，也可以只是一封早就写好的东西。她不是来吓人的；她怕的是这个家散了之后，活着的人无路可退。\n\n**那件心愿是什么**：一件“趁家里还有的时候做、能长久供养一族人”的事。可以是置一份产业、立一份规矩、存一笔公账、写下一册该记下的东西。它必须是实的，看得见、管得着、分得出钱粮。\n\n**那两件事、那两句话**：两件事是临别交代的两句要紧话（一桩喜事、一场要散的席），都不必解释，也不必是诗——可以是一句俗语、一句断语、一句家常话。最后留下的那两句话只是叫甲记着的，卡不解释它，只看甲记不记得住、往不往心里去。\n\n**注意**：卡停在“报丧的响声传来，甲还想再问”这一刻。不要写甲信不信、办不办，也不要写那句“非常之喜”是什么、有没有应验——那件事本身是后面的一张卡。",
