    "rel": "奇幻类/红楼梦/深宅大院/C3-05-摔在地上.md",
    "face": "家里新来的那个孩子，和这家原来的孩子见了面。\n\n这家原来的孩子，从小身上就戴着一件东西——一块玉、一枚牌、一个护符。家里人说这是他的命，谁也不能碰。全家上下，只有他一个人有。\n\n他先问她：你有这个吗？\n\n她回答说：没有。\n\n他愣了一下，忽然从脖子上把那件东西扯下来，用尽力气摔在地上。\n\n“你们都没有，就我有——那我不要它了。”",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲是这个孩子的家里人——父母、祖辈、照看他的人。如果玩家是这个家里的人，卡的重点就是“东西摔在地上，你是先去捡，还是先去看那个新来的孩子”。\n\n**玩家在哪**：玩家可以在场；也可以就是刚来的那个孩子，卡的重点变成“你第一天就惹出这样的事”；也可以不在场，事后从满屋子人的嘴里听说。\n\n**那件东西是什么**：一块玉、一枚牌、一个护符、一个胎记、一份只有他有的天赋、一笔只给他一个人的家产。它要满足两点：全家都把它当成这孩子的命；别人都没有。\n\n**摔得坏吗**：可以摔坏，也可以摔不坏。摔不坏更麻烦——它还在，事情就没有了结。\n\n**他为什么发作**：他发现自己和别人不一样；他想要一样东西；他想用摔掉它来证明自己不在乎；或者他是在试探这一家到底谁疼他。\n\n**哄的人是谁**：长辈、母亲、照看他的人、仆人。哄的话可以是真的，也可以是编的；编的那一套，日后会变成他自己的心结。\n\n**分类**：归奇幻类，因为这件东西本身是有灵的、和命连着的。如果放进现实类，把它改成“全家都当命的一件传家宝、一份凭据、一张单子”，骨架不变。\n\n**这是哪**：任何有“命物”和“说法”的世界。\n\n**注意**：卡停在“你们都没有，就我有——那我不要它了”这一刻。不要写长辈怎么哄、事情怎么收场。如果哄话是编的，记住它是编的——它会回来。",
