    "rel": "奇幻类/红楼梦/谶应异闻/C1-01-要孩子的人.md",
    "face": "那是一个再普通不过的午后。甲抱着孩子在门口，做些平常的事，或者只是站着。\n\n路那头来了两个人。他们样子有些古怪，衣服脏得看不出颜色，走路却比谁都稳当。他们本来在说话，走过甲身边的时候，忽然都停下了。\n\n其中一个人盯着甲怀里的孩子。他脸上的笑一点点垮下来，最后变成一种甲从来没见过的悲痛。他放声大哭。\n\n“这孩子，”他说，“留不住，还会拖累你们。”\n\n他伸出手：“把他给我。把他给我。”",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是玩家，也可以是玩家的配偶、家人、亲戚、朋友，或者玩家关系网里的任何一个人。最好让甲和玩家有关系——玩家越在乎甲，这张卡越重。如果玩家就是甲，把“甲”读成“你”。\n\n**玩家在哪**：玩家可以在现场，看着这件事发生；也可以不在场，事后从甲、家人、仆从、路人的口中听说。如果玩家不在场，卡的重点就从“当时的反应”变成“事后怎么处理”。\n\n**那两个人是谁**：不必是算命先生，也不必是乞丐。他们可以是游方人、异乡客、疯子、传教士、先知——任何“不该知道这件事的人”。他们的共同点只有两个：看起来不该知道，却偏偏知道；他们要的不是钱，是孩子。他们对甲的称呼也随设定换：“这位”“朋友”“旅人”“客人”，或者干脆不称呼。\n\n**这是哪**：时间、地点、时代、孩子的年龄、甲的身份，都可以随设定替换。唯一不能换的是：一个普通人，抱着一个他珍爱的孩子，遇见一个说出不祥之言的人。\n\n这张卡归在奇幻类：他们真的知道一些事。如果放进现实类故事，把他们改成“碰巧说中”或“另有所图”的人即可。",
