    "face": "甲家里添了一个孩子。\n\n孩子出生时，身上带着一样不该有的东西——一块玉、一个印记、一层膜、一道光。接生的人先看见，脸色都白了。\n\n消息传出去。有人说这是祥瑞，有人说这是妖异。\n\n孩子还在哭。家里人要决定，怎么对外说。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是玩家，也可以是玩家的配偶、家人、亲戚、朋友。甲家刚添了一个孩子。\n\n**玩家在哪**：玩家可以在场，看见那样东西；也可以不在场，事后从接生的人、家人、邻居的口中听说。如果玩家就是那个孩子，卡的重点就变成“你一出生，就被当成了一个说法”。\n\n**孩子身上带的是什么**：一块玉、一个印记、一层膜、一道光、一个预言、一个胎记、一种不该有的天赋。\n\n**说祥瑞的是谁**：长辈、祭司、医生、邻居、教会。\n\n**说妖异的是谁**：另一派长辈、政敌、教会、官府。\n\n**这是哪**：任何有“异象”和“说法”的世界。\n\n**注意**：不要写家里最后怎么处置；那是家里人的决定。卡停在“孩子出生了，说法已经传开”这一刻。如果放进现实类，把“异象”改成“孩子生来有某种缺陷、天赋或病”，说法仍然一样。",
