    "chapter": "谶应异闻",
    "rel": "奇幻类/红楼梦/谶应异闻/C8-01-像是成对的两句话.md",
    "face": "一个人病了好些天，一直在家养着，另一个人一直没来。\n\n这天他来了。两个人说了一会儿话，她忽然要看看他身上那件东西——家里说那是他的命，他整天带着，谁也不给细看。\n\n她把自己那件托在手掌上，念了上面的一行字；又把他的拿过去，念了那上面的一行。两行字，像是对着写出来的。\n\n旁边一个下人脱口说了一句：这两句，倒像是一对儿。\n\n可是这句话已经说出来了。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是带着旧物的那个人，也可以是凑过去看的人，也可以是那个脱口而出的下人。谁站在这场里，谁就要接住这句话。\n\n**玩家在哪**：玩家可以就是取出旧物的人——你要不要把她那件要过来看；可以是旁边看着的人；也可以是那个下人，一句实话出口，挨骂的、被打发走的都是你；也可以不在场，这句话日后由别人转述给你听。\n\n**两行字是什么**：两句吉祥话、两句祝词、两句箴言，各人对各人的。要紧的不是字，是：两句话长得像一对，而这两个人自己都从没把它当过一回事。\n\n**为什么是重的**：说出这句话之前，这只是两个亲戚家的孩子；说出来之后，这两件旧物、这两个人，都被别人放进了同一个说法里。往后他们做什么，旁人都要拿“一对”来量。\n\n**下人为什么说**：她只是说了她看见的。她挨的那顿骂、被支出去的那趟差事，也是这张卡的一部分。\n\n**旧物是什么**：一块玉、一枚牌、一个护符、一张纸、一串珠子、一个胎记。它可以真的是命物，也可以只是家里传下来的一句说法。\n\n**分类**：归奇幻类，因为“这两句话是一对”本身就是个预兆，迟早有人会把它当成预兆，拿它安排这两个人的将来。如果放进现实类，把它改成“两家人各有一句老话，正好配得上”，骨架不变。\n\n**这是哪**：任何有“信物”和“说法”的世界——家族、门派、婚约、结拜、公司里的两个继承人。\n\n**注意**：卡停在“这句话已经出来了”这一刻。不要写谁动了心，也不要写有没有人认这个说法。如果这张卡演下去，记下这句话是谁说的、谁听见了——它会回来找你。",
