    "chapter": "谶应异闻",
    "rel": "奇幻类/红楼梦/谶应异闻/C36-05-梦话.md",
    "face": "那个孩子在床上睡着。他身边坐着一个姑娘，正替他做一件贴身的针线。\n\n睡着的人忽然在梦里喊起来，说：那些出家人的话怎么信得？什么天定的姻缘？我偏要自己认。\n\n这位姑娘听了这句话，当时就怔住了。\n\n正好那个丫头走进来，笑着问：还没醒吗？她摇头。那丫头又说：我刚才碰见那两位姑娘，她们进来了没有？她说：没见她们进来。她又问那丫头：她们没告诉你什么？那丫头红了脸，笑着说：不过是她们那些玩话，有什么正经的。她笑着说：今天她们说的可不是玩话，我正要告诉你，你又忙忙地出去了。\n\n话没说完，外头有人来叫那个丫头。她笑着说：就是为那话来的。那个丫头只好叫起两个小丫头，跟她一起出去了。\n\n后来那丫头办完事回来，那孩子已经醒了，问起她出去做什么，她含糊答应。到了晚上人静，她才把这件事告诉他。至于他在梦里说过什么，没有人跟他提。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是睡着的那个人，可以是坐在床边听见的那个姑娘，可以是后来进来的那个丫头，也可以是外头来叫人的那位。甲是听见了、或者该不该说出口的那一个。\n\n**玩家在哪**：玩家可以就是坐在床边的那位——你听见了，这句话你带不带出去；可以是睡着的人——你什么都不知道，可你说的这句话已经进了别人的耳朵；可以是那个丫头，你进屋时只看见她怔着；也可以不在场，事后从别人口中听说那天有人在梦里喊过一句什么。\n\n**那两句话是什么**：两句关于婚姻的说法，一句说的是两个被安排在一起的人，一句说的是另外两个人。这两句话不是他自己编的，是外头的人早先给他家定下来的。他梦里那一声，是把其中一句推开了。\n\n**她为什么怔住**：她不是被吓着。她是听见了一个自己不能承认听过的东西——那句话说的是他不要那桩被安排好的事，而被安排的那一头，跟她有关。\n\n**她为什么不能提**：她坐的那个位子不是她的。她要是开口，先要交代自己为什么在这儿、坐了多久、做了什么。这句话带出去，第一个被人问的是她自己。\n\n**为什么这一张是重的**：这个家里关于这孩子将来跟谁的说法，是出家人早先给他家定下的。这一天，被定下的那个人在梦里把它推开了，而听见的人正好是说法那一头。他醒着的时候一个字没提过，可她往后再听人提这两句话，心里都有了底。\n\n**那个说法是什么**：一个预言、一句批语、一个相士或出家人早先留下的话。它可以真的应验，也可以只是家里传下来的一句说法——要紧的是，这个家里拿它当过一回事。\n\n**分类**：归奇幻类，因为整个骨架都建立在“外头的人早先定下过一句话，这句话迟早要应验”上面。如果放进现实类，把它改成“两家人早先谈过一门亲，他在梦里说了不要”，骨架不变。\n\n**这是哪**：任何有“定亲、婚约、指腹为婚、家里安排”的世界——家族、门派、两家人的约定、一份早签的合同。说法可以换成一句批语、一张字条、一个承诺。\n\n**注意**：卡停在“她怔住了”这一刻。不要写她后来跟谁提过，也不要写那个孩子最后知不知道。留在场上的是：**他在梦里把那个说法推开了，而听见的人正是被安排的那一头——这件事，两个人里只有一个人知道。**",
