    "rel": "现实类/红楼梦/丧葬礼仪/C2-05-女主人走了.md",
    "face": "甲家里的女主人病了。这病来得很急，没有拖多久。\n\n她走的那天，家里的人都在。她留下一个孩子，孩子还小，还不太明白发生了什么事。\n\n丧事办完，屋子里安静下来。孩子站在门口，等一个不会再回来的人。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是玩家，也可以是玩家的配偶、家人、亲戚、朋友。甲家里有一个孩子，还有一个刚走的女主人。\n\n**玩家在哪**：玩家可以在场，送她最后一程；也可以不在场，事后赶来，只看见一个还没有回过神的孩子。如果玩家就是那个孩子，卡的重点就变成“你还不懂‘走了’是什么意思”。\n\n**走的是谁**：母亲、妻子、养母、姐姐、祖母——就是家里那个撑着日常的人。\n\n**孩子多大**：孩子越小越难。但是孩子也不能小到成不了一张卡；至少要让旁人觉得“这孩子以后怎么办”。\n\n**这是哪**：任何世界。\n\n**注意**：不要写这一家马上决定把孩子送走还是留下，那是下一步。卡停在“屋子里安静下来”这一刻。",
