        "value": "玩家可以就是甲，手里已经被塞了东西；可以是指她站过去的那个长辈，一屋子人里只有她开口算数；可以是人群里的一个远亲，看着这个位置从别人手里换到另一个人手里；也可以不在场，事后听人说起那天是谁摔的。"
