        "value": "玩家可以是来安慰的那一个，你替对方卸多少责任、搭多少东西进去；可以是主家，你信不信这个说法、认不认这份人情；可以是衣服原来预备给的那一位，你的东西被拿去给了别人，你知不知道；也可以不在场，事后听说那天谁送了谁一套衣服。"
