        "value": "玩家可以是那个求她的人——你要不要拿一句空话去换这一夜；可以是那个撞进来的人——你要不要嚷出来；可以是那个女孩儿——你手上只有这一样东西，你要不要用它换一个出去的门；也可以不在场，日后从别人口中听说这一夜谁在后面屋里。"
