        "value": "玩家可以是那个把东西解出来的人——你走进去，身上还带着那件贴身的旧物，你解不解；可以是那个动手的人，东西摆在你眼前，你认不认这个错；可以是屋里的第三个人，你看着这一幕，谁也没法替他们说话；也可以不在场，事后听说“今天那两个人把话都说到底了”。"
