    "id": "C34-03-两条旧手巾",
    "number": "C34-03",
    "name": "两条旧手巾",
    "type": "信物 / 传话",
    "deck": "红楼梦",
    "category": "现实类",
    "chapter": "儿女情长",
    "rel": "现实类/红楼梦/儿女情长/C34-03-两条旧手巾.md",
    "face": "甲想打发人去看一个姑娘，又怕屋里贴身的那个人拦他。他先找了个由头，把那个人支到别处去借东西。人一走，他叫了另一个丫头来，让她去看那位姑娘，说：她要是问起我，你就说我好了。\n\n那个丫头说：空着手去不像回事，总得有个由头，不然我去了说什么。\n\n甲想了想，拿起两条自己用过的旧手巾，让她送去。\n\n那个丫头说：这种东西人家要吗。怕是要恼，说你拿她取笑。\n\n甲说：你放心，她自然知道。\n\n那个丫头拿着手巾去了。那边屋里没有点灯，人已经睡下。她隔着帐子说：他叫我给姑娘送手巾来。里面的人问：他送手巾来给我做什么。丫头说：不是新的，就是家里用旧的。里面的人听了，更加想不通，细想了半天才明白过来，说：放下，去吧。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是送东西的人，可以是收东西的人，也可以是跑腿的那个人。\n\n**玩家在哪**：玩家可以是送东西的人——你送什么、让谁去送；可以是跑腿的人——你不明白这是什么意思，你问不问、跟不跟人说；可以是收东西的人——你收不收、认不认这层意思；也可以不在场，事后听说那天有人送来两条用旧的手巾。\n\n**为什么是旧手巾**：新东西是礼，旧东西是贴身的东西。送一件自己用过的、不值钱的东西，意思不在东西上，在“这是我的”。\n\n**跑腿的人为什么不懂**：她不是这件事里的人。她只看见两条旧手巾，看不见里面的话。这一趟最要紧的地方就在这里：话是从一个完全不明白的人手里递过去的。\n\n**收的人为什么先恼后收**：她先想到的是“他拿我取笑”，再想到的是“他知道我会明白”。她收下的不是手巾，是“这件事只有我们两个人懂”。\n\n**代价**：她收下了，就等于应了。两个人从此有了一件只能私下来往的事，而且中间还经过了一个不明白的人。\n\n**这是哪**：任何有“托人带东西、一件旧物、一句说不出口的话”的地方——同学、同事、朋友之间、两个人的小圈子。\n\n**注意**：卡停在“放下，去吧”这一刻。不要写她后来怎么处理这两条手巾，也不要写跑腿的人回去怎么回话。这件东西留下了。",
