        "value": "玩家可以在场，坐在那间屋子里，跟甲一起认错人；也可以不在场，事后听甲当作笑话讲出来。如果玩家就是那个被错认的人（一个有体面的下人），卡的重点就变成“人家把你当主人，你要不要顺着接下去”。"
