        "value": "玩家可以在场，坐在这间屋子里一起等；也可以不在场，事后听说“那天在人家屋里坐了半日”。如果玩家就是那个叫人的人，卡的重点就变成“你把她晾在那里，是你拿捏她的第一步”。"
