    "face": "甲手里缺一笔钱，要办的事又非先花钱不可。他想起舅舅家开着铺子，就上门去，想先赊一份货，说好过了节按数把钱送来。\n\n舅舅冷笑：再别提赊欠。前儿铺子里一个伙计替亲戚赊了一批货，至今没还，我们大家赔上，立了合同，再不许替亲友赊欠。又说：如今这货也短，你拿现钱来买，也还没有。二则你那里有正经事？不过赊了去又是胡闹。\n\n甲笑着说：舅舅说的有理。只是我父亲没的时候，我还小，后来听母亲说，都亏了舅舅替我们出主意料理的丧事。难道舅舅不知道，还是有一亩地、两间房子在我手里花了？\n\n舅舅说：舅舅要有，还不是该当的。你但凡立得起来，到你们大屋里，下个气儿和他们的管事的嬉和嬉和，也弄个事儿管管。\n\n甲听不下去，起身告辞。舅舅说：怎么这么忙，你吃了饭去罢。\n\n这句话还没说完，舅母在里头接了话：你又糊涂了！说着没有米，这里买了半斤面来下给你吃，这会子还装胖呢。留下外甥挨饿不成？\n\n舅舅说：再买半斤来添上就是了。\n\n舅母就叫女儿：往对门去问一声，看能不能先借一点，明儿就送了来的。\n\n甲连说了几个不用费事，走得无影无踪。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲是那个来开口的人——家里败了、手头紧、要办的事又必须先花钱。甲不是来讨饭的，是来赊一份货、说好过节还钱的。甲可以就是玩家。\n\n**玩家在哪**：玩家可以就是甲，站在铺子里，把这句话说出口，再决定要不要留下来吃这顿饭；可以是那个舅舅，你手里确实有货，也确实是亲戚；可以是那个舅母，话由你说出来；也可以不在场，事后听甲回来说今天去了一趟舅舅家，什么也没办成。如果玩家就是甲，卡的重点就变成：你要办的事，必须先花钱，而这是你唯一能开口的地方。\n\n**为什么是舅舅**：这是甲眼下够得着、又不用先花钱的唯一一处。别处他开不了这个口，或者开过口没用。\n\n**舅舅为什么不肯赊**：他说的每一条都是真的。铺子立过合同，谁替亲友赊欠就罚；货确实短；他确实认定这个外甥拿不出正经事来。他不是在害人，他是在算自己的账。\n\n**他为什么还要数落一顿**：这一顿是舅舅替自己心里那点不安找的出口。他不出货，就得给这件事一个说法，于是说法落到甲身上：你立不起来、你不会算计、你不知好歹。\n\n**那句留饭是什么意思**：舅母嘴上留人吃饭，转身让女儿去对门借钱买面。这句话是当着甲说的，说给甲听，也说给舅舅听。她要的不是甲饿不饿，是让甲知道这一顿他家请不起，也让甲自己走。\n\n**他最后提了一句什么**：他提了。他说父亲死的时候他小，丧事是舅舅料理的。这句是甲唯一能拿出来的账，也是他最后一次试着把亲戚这层情分摆上桌。\n\n**为什么这一张是重的**：甲没有失去钱，也没有失去差事。他失去的是“亲戚可以开口”这件事。他从这道门里出来，往后遇到难处，这家他不会再来了。\n\n**这是哪**：任何有亲戚、有铺子、有“赊一回”的世界——小生意、作坊、店铺、宗族、同乡会。换到现代，就是上门借钱、赊一批货、请人先垫一笔。\n\n**注意**：卡停在“甲连说了几个不用费事，走得无影无踪”这一刻。不要写他有没有去别处弄到钱，也不要写这顿面后来吃没吃。留在场上的是：他到这家人门上开了一次口，然后他知道，这门往后不用再来了。",
