        "value": "卡停在“满院子的人都听见了。没有人敢拦他”这一刻。不要写这一家怎么处理他，也不要写那句话是真还是假——酒话里常常有真的。如果当家人下令捆人，记住：在一屋子人面前处置一个有功的老人，这件事本身就留下了把柄。"
