        "value": "玩家可以就是摔杯子的那个人——你还要不要往上告；可以是替他认下的人，这一句认下，你就替他背了一次错；可以是被溅了裙子的人，你什么都没做；也可以不在场，第二天从别人嘴里听见“昨晚不过是失手砸了个杯子”。"
