    "category": "现实类",
    "chapter": "深宅大院",
    "rel": "现实类/红楼梦/深宅大院/C13-07-来理家的人.md",
    "face": "家里出了大事，里里外外都要人拿主意。偏偏管着内务的那位女主人早就病着，起不来；家里辈分最高的那位又不在，出了门就不肯回来。\n\n外头要紧的人一个一个地来，都要有人陪；里头的事一样一样，都要有人问。甲一开口，底下的人看着甲，不答话。\n\n甲怕的不是钱不够，是让人看出来，这个家没有人管。\n\n于是甲去求那个能管得住她的长辈，说：要劳烦她一个月，来这儿照应照应，我就放心了。\n\n长辈说：她还年轻，没经过这样的事。办不好，反倒叫人笑话。\n\n甲不肯松口，说：除了她，再没有第二个人可以求了。说着，眼泪就下来了。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是玩家，也可以是主家的长辈、当家人、亡者的父亲或兄长。甲是那个“家里没有人可托、只好求外人”的人。甲求的时候越低声下气，这张卡就越足。\n\n**玩家在哪**：玩家可以就是要被托付的那一个，当场接不接、问不问条件、要不要用原来的旧人；可以是甲，就是那个低声下气求人的；可以是那位拦着的长辈，看甲一眼，话就咽下去；也可以是原来管家的那位女主人，躺着，听见外头把事交给了别人。如果玩家不在场，卡的重点就变成“这个家的权，交到了谁手上”。\n\n**为什么非得托外人**：被托付的人不该是名正言顺的继承人。名正言顺的人接手，那是过日子；外人接手，才是这张卡。她最好是晚辈、是别房的人、是从没在这个家里当过家的人。\n\n**原来那位为什么不在**：病、伤、产后、被夺了权、赌气躲起来、干脆走了，都可以。但是她的缺席必须在场面上看得见：账没有人记、客没有人陪、下人不敢答话。\n\n**那副牌子是什么**：一串钥匙、一枚印、一本账、一道口令、一张签字权。交出去的必须是“实权”，不是一句空话。\n\n**长辈为什么拦、为什么又松口**：她怕的是丢脸——“办不好，反倒叫人笑话”。甲拿死人和自己的脸面来压她，她就只能答应。这个“只能答应”，是整张卡的重量。\n\n**这是哪**：大宅、宗族大院、公司、医院、飞船都可以。\n\n**注意**：卡停在“除了她，再没有第二个人可求了”这一刻。不要写那个人后来怎么发号施令、下人们服不服、办成没办成。那一摊，是后面的事。",
