        "value": "玩家可以就是甲，当场定第一条规矩；可以是底下等着派差事的老仆，看着新来的当家人坐进去、迟迟不发话；可以是原来管这一摊事的人，眼看着自己的旧章程被一条条拆开；也可以不在场，事后听人说“新来的那位，一上手就列了五条”。"
