    "chapter": "深宅大院",
    "rel": "现实类/红楼梦/深宅大院/C20-02-没人问她.md",
    "face": "前面院子里正吵得响。当家的那位在正屋算账，一听就知道是那一位又发作了。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是玩家，也可以是当家的那位、旁边看着的人、刚才被骂的人。如果甲是当家的，这张卡的核心就是“要不要问这一句为什么”。\n\n**玩家在哪**：玩家可以是当家的那位，说软话把人带走，也可以直接问到底；可以是刚才被骂的人，眼看着救兵来了，却没有一句是替你说的；可以是过来劝的姑娘，站在旁边看了一遍怎么收场；也可以不在场，事后只听说“人被叫去喝酒了”。\n\n**为什么先问不得**：一问她为什么骂，这件事就得断个是非。断了是非，就得罪一头。当家的要的是这一刻别吵，不是对错。\n\n**老人要的是什么**：有人记得她。一顿热的、一句软话、拉着她走，比讲理有用。她骂的也许根本不是那个姑娘。\n\n**这一幕留下了什么**：院子里的人都看见了，闹一场不会挨罚，只会有人来请你去喝酒。往后谁心里有气，都知道该怎么用。\n\n**这是哪**：任何有“当家的、旧人、下不来台”的世界，比如家里、饭馆、工地、公司的走廊。\n\n**注意**：卡停在“那一位又发作了”这一刻。不要写当家的怎么圆过去、老人消没消气。这件事没有结论，正是这张卡要留下的东西。",
