    "chapter": "深宅大院",
    "rel": "现实类/红楼梦/深宅大院/C22-03-台上那个孩子.md",
    "face": "家里请了一班人来唱戏。席上坐着长辈、亲戚，还有几个年纪不大的姑娘。\n\n台上演戏的有两个小孩子，一个演女角，一个演丑角，都还很小。长辈看着觉得可怜，叫人另外拿了些吃食给他们，又另外赏了钱。\n\n有人笑着说：这个演女角的孩子，扮上以后活像一个人，你们再瞧不出来？\n\n席上有人心里明白，点了个头，没有说出来。另有一个人朝席上使了个眼色。\n\n一个心直口快的客人接了一句：我知道，像在座的那位姐姐。\n\n使眼色的那个人赶紧瞅了她一眼。席上的人听了，留神细看，都笑起来，说果然像她。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是玩家，也可以是席上任何一个人——说出这句话的客人、使眼色的那个、被比的那个姑娘、坐在旁边只笑不说的长辈。甲不必是说话的人。\n\n**玩家在哪**：玩家可以就是被比的那个姑娘，一屋子人正拿你和台上一个卖艺的孩子比，你接不接这句话；可以是说出这句话的人，话说出口才知道说错了；可以是那个使眼色的人，你要不要拦、拦得住拦不住；可以是坐在上首的长辈，管不管这一句玩笑；也可以不在场，事后听人说“那天席上有人拿她比了台上那个孩子”。\n\n**这句话为什么重**：台上那孩子是被人雇来取乐的，年纪小，没有名分。被比的那个人，是席上一位姑娘。这一比，比的不是长相，是身份。席上人人都看得出来，所以有人不说。\n\n**说的人有没有坏心**：多半没有。她就是嘴快，觉得自己说了句实话。卡不判她。\n\n**为什么有人使眼色**：使眼色的人怕被比的那个恼，也怕说的人得罪人。他拦的是这一句话，不是这个事实。\n\n**这件事留下了什么**：这一句玩笑说过，席上的人都记住了。往后再有人提起这两位姑娘，就多了一个能笑的说法。\n\n**这是哪**：任何“台上台下、有名分没名分”的地方——宴席、晚会、婚礼、公司年会、剧组探班、同学聚会。现代可以换成“有人说台上那个跑龙套的长得像在座某位”。\n\n**注意**：卡停在“众人都说果然像她”这一刻。不要写被比的那位姑娘当场怎么反应，也不要写这句话后来传了多远。**这一句玩笑是当着所有人说的，收不回来了。**",
