        "value": "玩家可以就是那个中间人，解释的话已经说出去了，收不回来；可以是收拾行李的客人，走不走由你定；可以是那位被比的姑娘，你还没出场，就已经被人拿来当了话柄；也可以不在场，事后听人说“那天夜里，那一位把行李都收拾好了”。"
