        "value": "玩家可以就是故意猜不着的那位，输多少、什么时候猜中，由你定；可以是那个被拉来传话的年轻人，你知道答案，要不要递这一句；可以是长辈，你猜中了，也知道是人家让的；可以是席上别的人，眼看着这一场是怎么被托住的；也可以不在场，事后听说“那天他猜谜猜了半天，罚了一堆东西”。"
