        "value": "玩家可以就是这位长辈，看完了，说不说由你定；可以是写下其中一条的人，你当时只是随手写的，不知道有人会这么读；可以是旁边看着的那位长辈，你看出他脸色变了；可以是来请他离席的人，你要不要问一句；也可以不在场，事后听说“那天他看完屏上的字，一句话也没说”。"
