    "chapter": "深宅大院",
    "rel": "现实类/红楼梦/深宅大院/C32-04-听来的话.md",
    "face": "他出门出得急，没有带扇子。她怕他热，拿了扇子赶着送出来。走到跟前，看见他一个人站着不动，眼睛直直的。她上去跟他说话，他没有认出她是谁，对着她说：好妹妹，我这颗心从来不敢说，今天胆子大了说出来，就是死了也甘心。我为你弄了一身的病，又不敢告诉人，只好忍着。等你的病好了，只怕我的病才好呢。睡里梦里也忘不了你。\n\n她听完，又怕又臊，忙推他：这是哪里的话，你是怎么着了，还不快去。他这才醒过来，才知道面前是她。他羞得满脸通红，还是呆呆的，接过扇子，一句话也没有，就走了。\n\n她站在原处，越想越怕：他刚才那些话一定是因为另一个人。照这样看来，将来难免要出不该出的事。可是怎么处置，才能免掉这场祸？她想到这儿，也呆呆地站住了。\n\n正好另一个人从那边走过来，问她：这么大的太阳底下，出什么神呢。她忙说：我才看见两只鸟打架，倒挺有意思，就看住了。那人又问：他刚穿了衣服，匆匆忙忙到哪里去了，我要叫住问他，他慌慌张张走过去，像没看见我。她说：上面叫他出去的。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是被认错的那一个，可以是听见的那一个，可以是后来路过问话的那一个，也可以是那个还不知情的人。\n\n**玩家在哪**：玩家可以是被认错的那一个，你把话说到哪一步才停；可以是听见的那一个，你说不说出去、跟谁说；可以是后来路过的那一个，你问得出来还是问不出来；也可以不在场，事后听说那天有人在太阳底下站了半天。\n\n**这件事为什么重**：不是他说错了什么，是他认错了人。他把只该对一个人说的话，说给了一个天天在他身边的人。听见的这个人，正好是管他日常起居的那一个。\n\n**听见的人怕什么**：她当场就明白这话是对谁说的。她怕的不是这句话，是这句话后面会发生的事。她没有资格管，也没有资格说，可是她天天在这屋里。\n\n**她为什么先说一个谎**：她把话咽下去了，先给自己找了一个说法——两只鸟打架。这个说法很小，没人会追着问。这句话一出，这件事就被她按住了。\n\n**为什么要加后头那一段**：同一天，另一个人路过，问的是同一件事。她答了一半。这张卡的分量就在这里：这件事从一个人手里，过到了第二个人手里。\n\n**这是哪**：任何有“贴身的人、要瞒的事、一个随口问的人”的地方——大宅、宿舍、公司、剧组。\n\n**注意**：卡停在她编完那个说法、把话咽下去这一刻。不要写她后来做了什么，也不要写那个人还会不会再说这句话。一句最要紧的话被一个不相干的人听去了，听的人还先替自己编了个说法。",
