    "chapter": "深宅大院",
    "rel": "现实类/红楼梦/深宅大院/C36-04-隔着窗看.md",
    "face": "中午，这院里没有一点声音，连廊下的鸟都睡着了。一个姑娘顺路走进来，想找屋里那个孩子说话解闷。\n\n她走进外间，看见伺候的丫头们横三竖四都睡着。进了里间，那孩子在床上睡着，他身边那个丫头坐在床沿上做针线，旁边放着一把赶虫子的刷子。\n\n那个丫头起身让她坐，又笑着说：好姑娘，你略坐一坐，我出去走走就来。说着就走了。\n\n这位姑娘只顾看那件针线，没留心，一蹲身，正好坐在刚才那个丫头坐的地方。她又看那件活计实在可爱，不由得拿起针来，替她接着做。\n\n过了一会儿，另有两个姑娘来了。一个转身到旁边一间屋子去找人，另一个走到窗外，隔着窗往里一看：那孩子穿着件薄衫子，随随便便睡着，这位姑娘坐在他身边做针线，旁边放着那把刷子。\n\n窗外这位看了，当时就呆住了，赶紧把身子一躲，又捂着嘴不敢笑出来，招手叫另一个过来看。另一个才要笑，忽然想起这位姑娘平日待她厚道，赶紧掩住嘴。她知道窗外这位嘴上不让人，怕她取笑，就拉着她说：走罢，我想起那个人来，她说中午要到池子边洗衣裳，想必去了，咱们找她去罢。\n\n窗外这位心里明白，冷笑了两声，只好跟她走了。屋里那位只刚做了两三个花瓣，什么都不知道。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是坐在屋里做针线的那个姑娘，可以是站在窗外看见的那个，可以是拉人走的那个，也可以是床上睡着的人。甲是看见的人，或者被看见的人。\n\n**玩家在哪**：玩家可以就是拉人走的那个——你已经看见了，你要不要拦、拦得住拦不住；可以就是窗外那个——你看见了，笑不笑出来、说给谁听，是你的事；可以就是屋里做针线的那个——你不知道有人来过，可你已经坐在了别人的位子上；也可以不在场，事后听说某天中午有人从窗外看见过一件事。\n\n**她为什么坐在那个位子上**：她不是有意的。屋里那个丫头请她坐，她就坐了；针线可爱，她就拿起来了。要紧的不是她存心不存心，是她坐在那儿，做着那件东西，样子看起来像是这屋里的什么人。\n\n**那件针线是什么**：一件贴身的活计、一件只有亲近的人才做的活计。它本身不值钱，值钱的是谁在替他做。\n\n**拉人走的那个为什么拦**：她不是护着屋里那位。她怕的是窗外这位嘴上不让人——她一开口，这件事就从“看见”变成“传出去”，伤的先是屋里那位。她拦下来，等于替屋里那位把这个中午压住了。\n\n**为什么这一张是重的**：这件事说破不值什么，压住却是要有人去压的。从这一天起，窗外那两位心里都有了一件不能提的事，而其中一个还欠了另一个一个人情——是她没让人笑出来。\n\n**代价**：拉人走的那个，从此在两个姑娘中间多了一层。她拦了一次，往后这位再有什么话要取笑，都得先看她一眼。屋里那位什么都不知道，可她坐过的那个位子，往后会有人记得。\n\n**这是哪**：任何有“一间屋子、一个中午、一件不该被人看见的小事”的地方——宿舍、办公室、亲戚家、剧组。位子可以换成工位、副驾、饭桌上的一把椅子。\n\n**注意**：卡停在“窗外这位冷笑了两声，只好跟她走了”这一刻。不要写屋里那位后来知不知道，也不要写这件事后来有没有被说出来。留在场上的是：**有两个人看见了，其中一个决定不让这件事传出去。**",
