        "value": "玩家可以就是甲，你想起这个人，屋里另一个人正劝你别多事；可以是劝他的那个人，你把难处一条一条摆出来，他一个字也没听；可以是那个被忘在外面的人，你听说他们做诗没叫你，急得不行，可你连出门都要问人；可以是家里做主的那位长辈，两个孩子在你跟前一个要接、一个说天晚了；也可以不在场，事后听说那天为接一个人闹了两趟。"
