        "value": "那个人欠甲一次，而且这一场从头到尾不是她的，往后提起来，说的是甲家的螃蟹、甲家的酒。甲出钱出东西，还担着“我替你办”的意思——她自己也清楚，所以东西还没出手，先补一句“你可别多心”。这一句是给出去的，也是划下来的：往后那个人再提这件事，就先欠了这一句人情。"
