    "chapter": "深宅大院",
    "rel": "现实类/红楼梦/深宅大院/C38-02-站着的那一桌.md",
    "face": "这一天在水边的亭子里摆开席面，主人请了家里最有年纪的那位老人，还有一位亲戚家的老太太。\n\n座次是早安排好的。上面一桌坐着老人、那位亲戚、三个年轻人；旁边一桌坐着一位太太和三个姑娘；靠门还有一小桌，坐的是两位媳妇，座位摆着，两个人都不敢坐，只在上面两桌跟前伺候。\n\n菜一样一样端上来。其中一个媳妇吩咐：这蟹不能一次多拿，仍旧放在蒸笼里，拿十个来，吃了再拿。她又要水洗了手，站在老人跟前剥肉，剥出来先让那位亲戚，亲戚说我自己掰着吃更好，她就端给老人。她又让人把酒烫得滚热拿上来，又让人去取洗手用的东西。\n\n主人家的姑娘陪老人吃了一个，就离席出来照应客人，又打发人盛两盘给屋里一个不上桌的姨奶奶送去。她看见那位媳妇跟出来，就说：你张罗不惯，你吃你的去，我先替你张罗，等散了我再吃。姑娘不肯。\n\n她又让人在廊上另摆了两席，把几位最有脸面的大丫头安排去坐。那几个人正吃得高兴，见这位媳妇来了，都站起来说：你又出来做什么？让我们也受用一会儿。\n\n这位媳妇笑着说：我替你们当差，倒不领情，还不快斟一杯酒来我喝。几个人笑着斟了酒送到她嘴边，她仰起脖子喝了，又喝了两杯，说：你们坐着吃罢，我可去了。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲可以是那两个站在桌边的媳妇里的一个，也可以是请客的姑娘、上桌的老人、廊上那几个大丫头，或者被盛了一盘菜送进去的那位姨奶奶。\n\n**玩家在哪**：玩家可以就是站着伺候的那个媳妇，一屋子人都在吃，你得先看谁的杯子空了；可以是主人家的姑娘，这席面是你请的，你从早张罗到晚，自己没吃几口；可以是廊上那几个大丫头，你们难得坐下吃一回，有人来了就得站起来；也可以不在场，事后听说那天摆了几桌，谁坐着，谁站着。\n\n**这张卡的重量在哪**：不在菜上，在座次上。谁坐上面，谁坐旁边，谁只有一张摆着不敢坐的桌子，是开席之前就定好的。老人、亲戚、三个年轻人坐在最上面的一桌；一位太太和三个姑娘坐在旁边一桌；两位媳妇的位置在靠门，她们从头到尾没有坐下。\n\n**为什么还要单给大丫头摆两席**：因为这些人平时不上桌。摆这两席，是这一天特别开恩。可她们还是得站起来——来的这个人身份比她们高。恩典给到了，位次没有变。\n\n**那位媳妇为什么能笑着喝那杯酒**：她替这一屋子人当差，只有到了廊上，她才被人敬一杯。她喝完了还得回去。她一边张罗，一边跟人说笑，这一顿饭才吃得下去。\n\n**代价是什么**：请客的姑娘把这场席面办成了，自己一天没上桌；站着伺候的两个人把老人这一桌伺候周全了，她们这一天的功夫就都在这两桌跟前。这两个人的名字，不在任何一张桌上。\n\n**这是哪**：任何有“主桌、次桌、伺候的人”的地方——婚宴、家宴、公司年会、剧组的盒饭棚。谁坐着吃、谁站着看、谁最后吃，随便哪一样都能顶替这套座次。\n\n**注意**：卡停在“你们坐着吃罢，我可去了”这一刻。不要写她们后来又吃了什么，也不要写那位媳妇回去以后怎么伺候。这一天的席面摆得很体面，体面是靠几个人没坐下换来的。",
