    "rel": "现实类/红楼梦/病榻医药/C11-02-熬不过年.md",
    "face": "里屋比外头暗。病人靠在褥子上，脸瘦得只剩一层皮。见有人进来，她要撑着起来，被人按住了。\n\n她拉着来人的手，先说自己有福气：公婆待她像亲女儿，夫妻两个从来没有红过脸，一家上下没有不疼她的。说了半天，她才说：如今得了这个病，我那一点要强的心，也没有了。\n\n又说：我自己想着，怕是撑不了太久了。\n\n屋里静了一下。\n\n来人刚要开口，她先笑了：神仙来了也没用。病能治，命治不了。我知道我这病，不过是挨日子。\n\n临走，她拉着来人不放，说：有工夫的时候，还求你过来看看我，咱们坐着说说话。\n\n她等着这一句答话。",
    "notes": "**合理化**：先确认这件事在玩家这个世界里说得通——人物、地点、时机都要合理。如果玩家在场不合理，就让他完全不出场，事后从别人口中听说。不要为了把玩家塞进场景而硬编。\n\n**甲是谁**：甲是来看她的人——亲戚、妯娌、旧日的相好、被家里派来探病的。甲就是那个被交代过“你去开导开导她”的人。\n\n**玩家在哪**：玩家可以是甲，坐在褥子边，被这几句话压住；可以是病人，这些话说到哪一步、说给谁听，由你定；可以是跟着进来的人，坐在对面椅子上；也可以不在场，事后听人转述“那天她说了句很不吉利的话”。\n\n**开导的人为什么开不了口**：家里派甲来，是要甲说宽心话的。宽心话还没出口，病人先把底交了——她把话说到头，就等于把甲的话堵死了。甲要么驳回她，要么认下。\n\n**病人为什么把话说到底**：能做的都做了——钱花了、大夫请了、长辈疼她。她只剩这一件事是自己能做的：把话说给一个肯听的人。她要的不是宽心，是有人来。\n\n**那句“病能治，命治不了”是什么**：不是绝望，是算过账。能治的家里都肯治，剩下那一份不归人管。\n\n**甲能怎么办**：驳回她（她得再解释一遍，等于替甲宽心）；哭（她反过来安慰甲）；岔开（她就把话收回去，从此不再提）；只坐着握住她的手（那也算答了）。每一种都有代价。\n\n**她是谁**：年纪不大、进门没几年、里外都说好的那个媳妇、女儿、儿媳。越是要强的人，说出这句话越重。\n\n**这是哪**：病房、内室、榻前、休养的地方，任何有人躺着而屋里人都装着没事的地方。\n\n**注意**：卡停在“她求甲常来，等一句答话”这一刻。不要写甲答了什么，也不要写她熬不熬得过这个年。她这一句已经交到甲手里了——甲带着它出门，就得决定把它交给谁。",
